from collections import OrderedDict
from copy import deepcopy
from datetime import datetime
from typing import Any, Dict, List, Optional, Union


def run(rows: List[Dict[str, Any]], reference: Dict[str, List[Dict[str, Any]]]) -> Dict[str, Any]:
    # ---- validation ----
    required_input_cols = ["Claim ID", "Employee Email", "Date", "Category", "Description", "Amount", "Team", "Role"]
    for i, row in enumerate(rows):
        for col in required_input_cols:
            if col not in row:
                raise ValueError(f"Missing column '{col}' in row {i}")

    staff = reference.get("staff")
    if staff is None:
        raise ValueError("Missing reference 'staff'")
    for i, ref_row in enumerate(staff):
        for field in ["email", "team", "role"]:
            if field not in ref_row:
                raise ValueError(f"Missing field '{field}' in staff reference row {i}")

    # ---- copy input (shallow copy of each row dict is sufficient since values are immutable) ----
    rows = [dict(row) for row in rows]

    # ---- helpers ----
    def blank(v: Any) -> bool:
        return v is None or (isinstance(v, str) and v.strip() == "")

    def text(v: Any) -> str:
        if v is None:
            return ""
        if isinstance(v, float) and v.is_integer():
            return str(int(v))
        return str(v)

    def normalize(v: Any, steps: List[str]) -> str:
        s = text(v)
        for step in steps:
            if step == "strip":
                s = s.strip()
            elif step == "upper":
                s = s.upper()
            elif step == "lower":
                s = s.lower()
            elif step == "collapse_spaces":
                s = " ".join(s.split())
            elif step == "digits_only":
                s = "".join(ch for ch in s if ch.isdigit())
        return s

    # ---- step 1: clean_text Employee Email ----
    for row in rows:
        val = row.get("Employee Email")
        if isinstance(val, str):
            s = val.strip()
            s = " ".join(s.split())  # collapse_spaces
            s = s.lower()  # case lower
            row["Employee Email"] = s if s != "" else None

    # ---- step 2: clean_text Category ----
    for row in rows:
        val = row.get("Category")
        if isinstance(val, str):
            s = val.strip()
            s = " ".join(s.split())  # collapse_spaces
            s = s.title()  # case title
            row["Category"] = s if s != "" else None

    # ---- step 3: lookup ----
    # build index from staff reference
    index: Dict[str, List[Dict[str, Any]]] = {}
    for ref_row in staff:
        key = normalize(ref_row.get("email"), ["strip", "lower"])
        if key != "":
            index.setdefault(key, []).append(ref_row)

    statuses = {"found": "matched", "not_found": "not in directory", "ambiguous": "check manually"}

    for row in rows:
        # ensure output columns exist
        for out_col in ["Team", "Role"]:
            if out_col not in row:
                row[out_col] = None

        key_val = row.get("Employee Email")
        k = normalize(key_val, ["strip", "lower"])

        if k != "" and k in index:
            matches = index[k]
            if len(matches) == 1:
                match = matches[0]
                # mode fill_blanks
                if blank(row["Team"]):
                    row["Team"] = match.get("team")
                if blank(row["Role"]):
                    row["Role"] = match.get("role")
                status = statuses["found"]
            else:
                status = statuses["ambiguous"]
        else:
            status = statuses["not_found"]

        row["Directory Match"] = status

    # ---- step 4: format_date ----
    input_formats = ["%Y-%m-%d", "%d/%m/%Y", "%d %b %Y"]
    output_format = "%Y-%m-%d"

    for row in rows:
        val = row.get("Date")
        if isinstance(val, str) and not blank(val):
            s = val.strip()
            parsed = None
            for fmt in input_formats:
                try:
                    parsed = datetime.strptime(s, fmt)
                    break
                except ValueError:
                    continue
            if parsed is not None:
                row["Date"] = parsed.strftime(output_format)
            # else keep original (invalid='keep')

    # ---- step 5: compute Amount incl GST ----
    def evaluate_expression(expr: str, row: Dict[str, Any]) -> Optional[float]:
        # tokenize
        tokens = []
        i = 0
        while i < len(expr):
            ch = expr[i]
            if ch.isspace():
                i += 1
                continue
            if ch in "+-*/()":
                tokens.append(ch)
                i += 1
            elif ch == "{":
                j = expr.find("}", i)
                if j == -1:
                    raise ValueError("Unclosed column reference")
                col_name = expr[i + 1:j]
                tokens.append(("COL", col_name))
                i = j + 1
            elif ch.isdigit() or ch == ".":
                j = i
                while j < len(expr) and (expr[j].isdigit() or expr[j] == "."):
                    j += 1
                num_str = expr[i:j]
                tokens.append(("NUM", float(num_str) if "." in num_str else int(num_str)))
                i = j
            else:
                raise ValueError(f"Unexpected character: {ch}")
        tokens.append(("EOF", None))

        # use a list to hold position (mutable, no nonlocal needed)
        pos = [0]

        def peek():
            return tokens[pos[0]][0]

        def consume(tok_type=None):
            tok = tokens[pos[0]]
            if tok_type and tok[0] != tok_type:
                raise ValueError(f"Expected {tok_type}, got {tok[0]}")
            pos[0] += 1
            return tok

        def parse_factor():
            tok = peek()
            if tok == "-":
                consume()
                val = parse_factor()
                return -val if val is not None else None
            elif tok == "(":
                consume("(")
                val = parse_expr()
                consume(")")
                return val
            elif tok == "NUM":
                return consume()[1]
            elif tok == "COL":
                _, col_name = consume()
                v = row.get(col_name)
                if isinstance(v, (int, float)) and not isinstance(v, bool):
                    return float(v)
                return None
            else:
                raise ValueError(f"Unexpected token: {tok}")

        def parse_term():
            val = parse_factor()
            while peek() in ("*", "/"):
                op = consume()[0]
                rhs = parse_factor()
                if val is None or rhs is None:
                    val = None
                elif op == "*":
                    val = val * rhs
                elif op == "/":
                    if rhs == 0:
                        val = None
                    else:
                        val = val / rhs
            return val

        def parse_expr():
            val = parse_term()
            while peek() in ("+", "-"):
                op = consume()[0]
                rhs = parse_term()
                if val is None or rhs is None:
                    val = None
                elif op == "+":
                    val = val + rhs
                elif op == "-":
                    val = val - rhs
            return val

        result = parse_expr()
        if peek() != "EOF":
            raise ValueError("Extra tokens after expression")
        return result

    for row in rows:
        result = evaluate_expression("{Amount} * 1.1", row)
        if result is not None:
            result = round(result, 2)
        row["Amount incl GST"] = result

    # ---- step 6: flag ----
    for row in rows:
        if "Needs Approval" not in row:
            row["Needs Approval"] = None

        # condition: Amount gt 500
        amount = row.get("Amount")
        cond_met = False
        if isinstance(amount, (int, float)) and not isinstance(amount, bool):
            cond_met = amount > 500
        # else cond_met stays False (strings, None, etc.)

        row["Needs Approval"] = "Yes" if cond_met else "No"

    # ---- step 7: summarize ----
    # group by Team
    groups: Dict[str, List[Dict[str, Any]]] = OrderedDict()
    for row in rows:
        team_val = row.get("Team")
        key = text(team_val).strip() or "(blank)"
        if key not in groups:
            groups[key] = []
        groups[key].append(row)

    summary_records = []
    for team_key, group_rows in groups.items():
        # count Claim ID non-blank
        claim_count = sum(1 for r in group_rows if not blank(r.get("Claim ID")))
        # sum Amount numeric only (sum of none = 0)
        amount_sum = 0.0
        for r in group_rows:
            amt = r.get("Amount")
            if isinstance(amt, (int, float)) and not isinstance(amt, bool):
                amount_sum += float(amt)
        amount_sum = round(amount_sum, 2)

        summary_records.append({
            "Team": team_key,
            "Claims": claim_count,
            "Total Amount": amount_sum
        })

    # ---- build output rows with exact column order ----
    output_cols = [
        "Claim ID", "Employee Email", "Date", "Category", "Description",
        "Amount", "Amount incl GST", "Team", "Role", "Directory Match", "Needs Approval"
    ]
    output_rows = []
    for row in rows:
        out_row = {col: row.get(col) for col in output_cols}
        output_rows.append(out_row)

    return {
        "rows": output_rows,
        "sheets": {"Totals by Team": summary_records}
    }
